namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (principal is null || resource is null || request is null)
            return Deny("missing-context");

        var failure = GetIdentityFailure(principal, resource);
        if (failure is not null)
            return Deny(failure);

        failure = GetPrincipalFailure(principal, resource);
        if (failure is not null)
            return Deny(failure);

        failure = GetRequestContextFailure(principal, resource, request);
        if (failure is not null)
            return Deny(failure);

        var administrator = principal.Roles.Contains("administrator");
        var operatorRole = principal.Roles.Contains("operator");
        var auditor = principal.Roles.Contains("auditor");
        var owner = principal.Id == resource.OwnerId;
        var delegated = delegations.HasDelegation(principal.Id, resource.Id, request.Action);

        if (request.BreakGlass)
            return DecideBreakGlass(administrator, request.StrongAuthentication);

        failure = GetRestrictionFailure(resource, request);
        if (failure is not null)
            return Deny(failure);

        failure = GetAuthorizationFailure(request, administrator, operatorRole, auditor, owner, delegated);
        if (failure is not null)
            return new AccessDecision(false, failure, failure != "read-not-authorised");

        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(true, delegated ? "delegated" : "role-or-ownership", outsideBusinessHours || resource.Classification == "restricted");
    }

    private static string? GetIdentityFailure(Principal principal, Resource resource)
    {
        return string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id)
            ? "invalid-identity"
            : null;
    }

    private static string? GetPrincipalFailure(Principal principal, Resource resource)
    {
        if (principal.Suspended)
            return "principal-suspended";
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return "tenant-mismatch";
        return null;
    }

    private static string? GetRequestContextFailure(Principal principal, Resource resource, AccessRequest request)
    {
        if (resource.Locked && request.Action != "read")
            return "resource-locked";
        if (request.MinuteOfDay is < 0 or > 1439)
            return "invalid-time";
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return "challenge-required";
        return null;
    }

    private static AccessDecision DecideBreakGlass(bool administrator, bool strongAuthentication)
    {
        return !administrator || !strongAuthentication
            ? Deny("invalid-break-glass")
            : new AccessDecision(true, "break-glass", true);
    }

    private static string? GetRestrictionFailure(Resource resource, AccessRequest request)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return "strong-authentication-required";
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return "trusted-network-required";
        return null;
    }

    private static string? GetAuthorizationFailure(
        AccessRequest request,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated)
    {
        var failure = GetDeleteFailure(request, administrator);
        if (failure is not null)
            return failure;

        failure = GetWriteFailure(request, administrator, operatorRole, owner, delegated);
        if (failure is not null)
            return failure;

        failure = GetReadFailure(request, administrator, operatorRole, auditor, owner, delegated);
        if (failure is not null)
            return failure;

        return request.Action is not ("read" or "write" or "delete") ? "unknown-action" : null;
    }

    private static string? GetDeleteFailure(AccessRequest request, bool administrator)
    {
        return request.Action == "delete" && !administrator ? "administrator-required" : null;
    }

    private static string? GetWriteFailure(
        AccessRequest request,
        bool administrator,
        bool operatorRole,
        bool owner,
        bool delegated)
    {
        if (request.Action != "write")
            return null;
        return administrator || operatorRole || owner || delegated ? null : "write-not-authorised";
    }

    private static string? GetReadFailure(
        AccessRequest request,
        bool administrator,
        bool operatorRole,
        bool auditor,
        bool owner,
        bool delegated)
    {
        if (request.Action != "read")
            return null;
        return administrator || operatorRole || auditor || owner || delegated ? null : "read-not-authorised";
    }

    private static AccessDecision Deny(string reason)
    {
        return new AccessDecision(false, reason, true);
    }
}
